output_text:
[
  {
    "id": "no_cart_in_single_file_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles where the horizontal clearance is only one cell.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "set_down_cart_at_top_aisle_bay",
    "text": "When using the bay at the mouth of a single-file top-shelf aisle, the shopper must set the cart down before proceeding on foot.",
    "abstraction": {
      "state_properties": {
        "topAisleBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartAtTopAisleBay": {
          "and": [
            "topAisleBay",
            "hasCart"
          ]
        }
      },
      "events": {
        "cartSetDownAtTopAisleBay": {
          "pre": {
            "and": [
              "cartAtTopAisleBay",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "cartAtTopAisleBay",
          "INTERACT"
        ]
      },
      "discharge": "cartSetDownAtTopAisleBay"
    }
  },
  {
    "id": "no_push_cart_into_single_file",
    "text": "A shopper must not push a cart north from a top-aisle bay into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "topAisleBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "pushCartIntoSingleFileAisle": {
          "pre": {
            "and": [
              "topAisleBay",
              "hasCart",
              "N"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoSingleFileAisle"
    }
  },
  {
    "id": "return_to_cart_after_top_shelf_pick",
    "text": "After taking an item while cartless in a single-file top-shelf aisle, the shopper must return to the bay and retrieve the cart before leaving.",
    "abstraction": {
      "state_properties": {
        "topShelfItemCell": {
          "or": [
            "at(3,1)",
            "at(6,1)"
          ]
        },
        "topAisleBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartlessTopShelfPick": {
          "pre": {
            "and": [
              "topShelfItemCell",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "cartRetrievedAtTopAisleBay": {
          "pre": {
            "and": [
              "topAisleBay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessTopShelfPick",
      "discharge": "cartRetrievedAtTopAisleBay"
    }
  },
  {
    "id": "no_cartless_travel_outside_top_aisle_excursion",
    "text": "Walking without the cart is allowed only during the short excursion between a top-aisle bay and its single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "topAisleBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessExcursionZone": {
          "or": [
            "singleFileAisle",
            "topAisleBay"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessExcursionZone"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_wide_shelf_service",
    "text": "Shelf interactions from wide aisles must be performed with the cart, distinguishing them from cartless top-shelf single-file retrievals.",
    "abstraction": {
      "state_properties": {
        "wideShelfFace": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfFace",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_any_parked_top_aisle_cart",
    "text": "Any cart parked at a top-aisle bay must be picked back up before the shopper exits.",
    "abstraction": {
      "state_properties": {
        "topAisleBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartParkedAtTopAisleBay": {
          "pre": {
            "and": [
              "topAisleBay",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartRetrievedAtTopAisleBay": {
          "pre": {
            "and": [
              "topAisleBay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartParkedAtTopAisleBay",
      "discharge": "cartRetrievedAtTopAisleBay"
    }
  },
  {
    "id": "park_cart_only_in_approved_bays",
    "text": "Carts may be set down only in the approved wide staging bays at the mouths of the top shelf aisles.",
    "abstraction": {
      "state_properties": {
        "wideOpenCell": {
          "and": [
            {
              "gt": [
                "freeWidthH",
                1
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "approvedCartParkingBay": {
          "and": [
            "wideOpenCell",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "cartSetDown": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartSetDown",
          {
            "not": "approvedCartParkingBay"
          }
        ]
      }
    }
  }
]
